                ['id' => 'ch6-q8', 'text' => 'برای معرفی پروژه منتشرشده، چه چیزی ضروری است؟', 'options' => ['فقط یک لینک', 'پست معرفی، دموی کوتاه و صفحه ارائه', 'تبلیغ پولی', 'هیچ‌چیز'], 'correct' => 1, 'topic' => 'انتشار و ارائه'],
            ]],
        ];

        foreach ($exams as $index => $examData) {
            // A fresh host has no chapters yet; create the shell row so the
            // exam FK holds. firstOrCreate never overwrites admin edits.
            Chapter::firstOrCreate(['id' => $examData['chapter_id']], ['index' => $index + 1, 'title' => $examData['title'], 'free' => $index === 0]);
            $exam = Exam::updateOrCreate(['id' => $examData['id']], ['chapter_id' => $examData['chapter_id'], 'title' => $examData['title'], 'duration_minutes' => $examData['duration_minutes'], 'pass_score' => $examData['pass_score']]);
            foreach ($examData['questions'] as $q) {
                ExamQuestion::updateOrCreate(['id' => $q['id']], ['exam_id' => $exam->id, 'text' => $q['text'], 'options' => $q['options'], 'correct' => $q['correct'], 'topic' => $q['topic']]);
            }
        }
    }
}
